"""Curated points verified against OSM, exact OSM lines; no illustrative scheme georeferencing."""
import json,pathlib,xml.etree.ElementTree as ET,math,hashlib
ROOT=pathlib.Path(__file__).resolve().parents[1];RAW=ROOT/'data/landscape';OUT=ROOT/'public/region/catalog';OUT.mkdir(exist_ok=True)
def dist(a,b):
 r=math.pi/180;return 12742.0176*math.asin(min(1,math.sqrt(math.sin((a[1]-b[1])*r/2)**2+math.cos(a[1]*r)*math.cos(b[1]*r)*math.sin((a[0]-b[0])*r/2)**2)))
sources=json.load(open(RAW/'geocoding.json'));spec=[('bannoye',0,'ГЛЦ Банное','https://bannoye.com/glc/','Горнолыжный центр над озером Банное. Основной комплекс обслуживает гондольная канатная дорога; предусмотрена отдельная учебная зона.'),('rodeo',1,'Родео-парк, Учалы','https://vk.com/rodeopark','Парк катания и тренировок в Учалах. Зимние спуски и тренировочные объекты требуют сверки назначения.'),('zavyaliha',2,'Завьялиха','https://zavyaliha.su/','Горнолыжный курорт возле Трёхгорного.'),('euroasia',3,'Евразия, Куса','https://euroasia.su/sky-slopes/','Горнолыжный курорт в Кусе с учебными и спортивными спусками.'),('sunny-valley',4,'Солнечная долина','https://dolina.su/','Горнолыжный курорт возле Миасса и Сыростана.'),('minyar',5,'ГЛЦ Миньяр','https://www.gsminyar.ru/','Горнолыжный центр возле Миньяра. Актуальные условия работы требуют проверки.'),('adzhigardak',6,'Аджигардак','https://adzhigardak.ru/','Горнолыжный центр возле Аши. Сведения о реконструкции и текущем режиме требуют подтверждения.')]
places=[];routeids=[];audit=[]
for id,idx,name,url,desc in spec:
 match=sources[idx]['results'][1 if id=='adzhigardak' else 0];point=[float(match['lon']),float(match['lat'])];km=round(dist(point,[58.4099549,53.9680705]),1)
 if km>200:audit.append({'id':id,'excluded':'outside 200 km','distanceKm':km});continue
 path=RAW/(id+'.xml');lines=[]
 if path.exists():
  root=ET.parse(path).getroot();nodes={n.get('id'):[float(n.get('lon')),float(n.get('lat'))] for n in root.findall('node')}
  for w in root.findall('way'):
   t={x.get('k'):x.get('v') for x in w.findall('tag')};refs=[x.get('ref') for x in w.findall('nd')];kind=t.get('piste:type');lift=t.get('aerialway')
   if not (kind or lift) or lift in ['pylon','station'] or not all(r in nodes for r in refs) or len(refs)<2:continue
   # Tubing and nordic retain their own type; never counted as downhill by default.
   number=t.get('ref') or t.get('piste:ref');category='nordic' if kind=='nordic' else 'tubing' if kind in ['sled','sleigh','tubing'] else 'lift' if lift else 'ski';rid=id+'/way/'+w.get('id');routeids.append(rid)
   props={'id':'way/'+w.get('id'),'routeId':rid,'placeId':id,'name':t.get('name') or t.get('piste:name') or ('Подъёмник' if lift else 'Маршрут OSM'),'number':number,'category':category,'difficultyOsm':t.get('piste:difficulty','unknown'),'tags':t,'geometryVerifiedByResort':False,'operationalStatus':None,'sourceUrl':'https://www.openstreetmap.org/way/'+w.get('id'),'checkedOn':'2026-10-23'}
   lines.append({'type':'Feature','properties':props,'geometry':{'type':'LineString','coordinates':[nodes[r] for r in refs]}})
  coords=[c for f in lines for c in f['geometry']['coordinates']];bounds=[min(p[0] for p in coords),min(p[1] for p in coords),max(p[0] for p in coords),max(p[1] for p in coords)] if coords else None
  (OUT/(id+'.geojson')).write_text(json.dumps({'type':'FeatureCollection','features':lines},ensure_ascii=False,separators=(',',':')))
  audit.append({'id':id,'sourceSha256':hashlib.sha256(path.read_bytes()).hexdigest(),'features':len(lines),'downhill':sum(f['properties']['category']=='ski' for f in lines),'note':'OSM route types retained, not an official resort count'})
 else:bounds=None
 places.append({'id':id,'name':name,'kind':'resort' if id!='rodeo' else 'training-park','category':'ski','coordinates':point,'coordinateSource':'https://www.openstreetmap.org/'+match['osm_type']+'/'+str(match['osm_id']),'coordinateStatus':'osm-reference-matched','sourceUrl':url,'description':desc,'distanceKm':km,'major':True,'zoneRadiusKm':4,'geometryUrl':('region/catalog/'+id+'.geojson') if lines else None,'bounds':bounds,'checkedOn':'2026-10-23'})
# Ufa ski centre source is the sports object by address, not the ambiguous city-centre name hit.
for id,name,match,url,category,desc in [('ak-yort','Ак Йорт',json.load(open(RAW/'ak-yort-geocoding.json'))[0],'https://akiort.ru/','ski','Городской горнолыжный комплекс в Уфе. Геометрия спусков здесь пока не подтверждена.'),('ufa-biathlon','СОК «Биатлон», Уфа',sources[14]['results'][0],'https://biathlonufa.ru/trassy/','nordic','Биатлонный комплекс с опубликованными зимними кругами. Доступ к тренировочной территории необходимо уточнять.')]:
 point=[float(match['lon']),float(match['lat'])];km=round(dist(point,[58.4099549,53.9680705]),1);places.append({'id':id,'name':name,'kind':'resort' if category=='ski' else 'nordic','category':category,'coordinates':point,'coordinateSource':'https://www.openstreetmap.org/'+match['osm_type']+'/'+str(match['osm_id']),'coordinateStatus':'osm-reference-matched','sourceUrl':url,'description':desc,'distanceKm':km,'major':True,'geometryUrl':None,'accessNote':'Наличие объекта не подтверждает свободный доступ или работу сегодня.'})
ethno=json.load(open(ROOT/'src/landscape/ethnopark.json'));places.append({'id':'ethnopark','name':ethno['name'],'kind':'ethnopark','category':'interesting','coordinates':ethno['center'],'coordinateSource':ethno['sourceUrl'],'coordinateStatus':'owner-provided','sourceUrl':ethno['sourceUrl'],'description':ethno['description'],'major':True,'photo':None})
# Unresolved entries are retained for the editor, without invented point positions or lines.
unresolved=[{'id':id,'name':name,'category':category,'coordinates':None,'status':'coordinate-unconfirmed','note':note} for id,name,category,note in [('kushtau','Куш-Тау','ski','Точная точка не подтверждена полученными источниками.'),('assy-tau','Ассы-Тау','ski','Противоречивые сведения о расположении и работе.'),('beloretsk-ski','Лыжная база и биатлон Белорецка','nordic','Геокодер вернул Межгорье; эта точка отвергнута.'),('uchaly-rollers','Лыжероллерная трасса Учалов','nordic','Вход, геометрия и зимний доступ не подтверждены.'),('magnitogorsk-eco','Экологический парк Магнитогорска','nordic','Точный вход лыжни и зимняя геометрия не подтверждены.'),('abzakovo-biathlon','Биатлонный центр Абзаково','nordic','Нужна привязка стадиона; наличие лыжни на сайте не задаёт точную геометрию.')]]
(ROOT/'src/region/winter-places.json').write_text(json.dumps(places,ensure_ascii=False,indent=2)+'\n');(ROOT/'src/region/catalog-routes.json').write_text(json.dumps(routeids)+'\n');(OUT/'audit.json').write_text(json.dumps({'checkedOn':'2026-10-23','places':audit,'unresolved':unresolved,'excluded':['Зирган-Тау: возобновление работы не подтверждено'],'radiusKm':200,'distanceKind':'geodesic straight-line approximation'},ensure_ascii=False,indent=2)+'\n')
print('Catalog:',len(places),'points;',len(routeids),'OSM lines;',len(unresolved),'unresolved points not invented')
